// Conversion from OpenTelemetry SDK spans (used by exporters and the in-memory fake)

const KIND_NAMES: Record<number, SpanKindName> = {
  [SpanKind.INTERNAL]: "internal",
  [SpanKind.SERVER]: "server",
  [SpanKind.CLIENT]: "client",
  [SpanKind.PRODUCER]: "producer",
  [SpanKind.CONSUMER]: "consumer",
};

/** Maps an OpenTelemetry `SpanKind` to the query-model name. */
export function spanKindName(kind: SpanKind): SpanKindName {
  return KIND_NAMES[kind] ?? "unspecified";
}

/** Converts an OpenTelemetry `HrTime` to epoch microseconds. */
export function hrTimeToMicros(time: HrTime): number {
  return time[0] * 1_000_000 + Math.floor(time[1] / 1000);
}

function toSpanAttributes(input: OtelAttributes | undefined): SpanAttributes {
  const out: SpanAttributes = {};
  for (const [key, value] of Object.entries(input ?? {})) {
    if (value === undefined) continue;
    out[key] = Array.isArray(value)
      ? value.filter((v): v is string | number | boolean => v !== null && v !== undefined)
      : value;
  }
  return out;
}

/** Converts a finished OpenTelemetry SDK span into the query model. */
export function readableSpanToSpan(span: ReadableSpan): Span {
  const ctx = span.spanContext();
  const serviceName = span.resource.attributes["service.name"];
  const startMicros = hrTimeToMicros(span.startTime);
  const endMicros = hrTimeToMicros(span.endTime);
  const status: Span["status"] = {
    code:
      span.status.code === SpanStatusCode.ERROR
        ? "error"
        : span.status.code === SpanStatusCode.OK
          ? "ok"
          : "unset",
  };
  if (span.status.message !== undefined && span.status.message !== "")
    status.message = span.status.message;
  const out: Span = {
    traceId: ctx.traceId,
    spanId: ctx.spanId,
    name: span.name,
    kind: spanKindName(span.kind),
    serviceName:
      typeof serviceName === "string" && serviceName !== "" ? serviceName : "unknown_service",
    startMicros,
    endMicros,
    durationMicros: Math.max(0, endMicros - startMicros),
    status,
    attributes: toSpanAttributes(span.attributes),
    events: span.events.map((e) => ({
      name: e.name,
      timeMicros: hrTimeToMicros(e.time),
      attributes: toSpanAttributes(e.attributes),
    })),
    links: span.links.map((l) => ({
      traceId: l.context.traceId,
      spanId: l.context.spanId,
      attributes: toSpanAttributes(l.attributes),
    })),
  };
  const parent = span.parentSpanContext?.spanId;
  if (parent !== undefined && parent !== "") out.parentSpanId = parent;
  return out;
}
